const DEFAULTS = {
  color: '#8D04FD',
  opacity: 0.6,
  fit: 0.9, // shape occupies this fraction of the mount (contain)
  sampleGap: 11, // source px between samples → controls dot count/spacing
  maxDots: 900, // hard cap (perf guard; logs if the sample would exceed it)
  dotRadiusScale: 0.5, // visual radius = sampleGap * this (source px)
  physicsRadiusScale: 0.44, // collision radius = sampleGap * this (slightly < half-gap so rest overlap is gentle)
  reveal: {
    duration: 1.3, // per-dot bloom duration (s)
    staggerSpread: 0.7, // total spread of per-dot delays (s) — radial bloom from the centroid
    scatterMin: 0.5, // scatter start distance as a fraction of shape radius
    scatterMax: 1.6,
    start: 'top 75%', // ScrollTrigger start (overridable via data-reveal-start)
  },
  physics: {
    // NOTE: matter integrates force as accel·Δt² (Δt≈16.7 → ×~278), so these look tiny on purpose.
    stiffness: 0.00006, // spring pull back toward home (higher = holds formation tighter)
    frictionAir: 0.12, // damping — how quickly a jiggle settles
    restitution: 0.35, // bounciness on collision
    jitter: 0.0006, // perpetual random force so the field keeps a gentle zero-g shimmer at rest
    maxSpeed: 12, // px/step velocity clamp — safety rail so the sim can never blow up to NaN
  },
  repel: {
    radius: 95, // cursor influence radius (display px)
    strength: 0.9, // push strength
  },
  dprCap: 2,
};

function deepMerge(a, b) {
  const o = Array.isArray(a) ? a.slice() : { ...a };
  for (const k in b || {}) o[k] = b[k] && typeof b[k] === 'object' && !Array.isArray(b[k]) ? deepMerge(o[k] || {}, b[k]) : b[k];
  return o;
}

// deterministic hash → [0,1) so scatter/jitter are stable across reloads (no Math.random at build parity)
const rand = (n) => {
  const h = Math.sin(n * 127.1 + 311.7) * 43758.5453;
  return h - Math.floor(h);
};
const easeOutExpo = (x) => (x >= 1 ? 1 : 1 - Math.pow(2, -10 * x));

class DotField {
  constructor(mount, overrides = {}) {
    if (!window.Matter) {
      // eslint-disable-next-line no-console
      console.warn('[modernvivo] dotfield: matter.js not found. Add the matter.min.js CDN script before dist/index.js.');
      return;
    }
    this.mount = mount;
    this.config = deepMerge(DEFAULTS, overrides);
    this.reduced = matchMedia('(prefers-reduced-motion: reduce)').matches;

    this.canvas = document.createElement('canvas');
    this.canvas.style.cssText = 'position:absolute;inset:0;width:100%;height:100%;display:block;';
    // keep the mount a positioning context if it isn't already
    if (getComputedStyle(mount).position === 'static') mount.style.position = 'relative';
    mount.appendChild(this.canvas);
    this.ctx = this.canvas.getContext('2d');

    this.engine = Matter.Engine.create({ gravity: { x: 0, y: 0, scale: 0 } });
    this.world = this.engine.world;
    this.dots = []; // { body, homeX, homeY, fromX, fromY, delay, r }
    this.walls = [];
    this.pointer = { x: -1e5, y: -1e5, active: false };

    this._phase = 'idle'; // idle → revealing → physics
    this._revealElapsed = 0;
    this._revealTotal = this.config.reveal.duration + this.config.reveal.staggerSpread;
    this._started = false;
    this._visible = true;
    this._raf = false;

    this._tick = this._tick.bind(this);
    this._onPointer = this._onPointer.bind(this);
    this._onPointerLeave = () => (this.pointer.active = false);

    this._buildFromSVG(); // async → sets up dots, then arms the scroll trigger
  }

  // Rasterize the artwork offscreen, sample on a grid, and collect dot centers in source space.
  _buildFromSVG() {
    const svg =
      '<svg xmlns="http://www.w3.org/2000/svg" width="' + SVG_W + '" height="' + SVG_H + '" viewBox="0 0 ' + SVG_W + ' ' + SVG_H + '">' +
      '<path d="' + PATH_D + '" fill="#ffffff"/></svg>';
    const img = new Image();
    img.onload = () => {
      const off = document.createElement('canvas');
      off.width = SVG_W;
      off.height = SVG_H;
      const octx = off.getContext('2d', { willReadFrequently: true });
      octx.drawImage(img, 0, 0, SVG_W, SVG_H);
      const data = octx.getImageData(0, 0, SVG_W, SVG_H).data;

      const gap = this.config.sampleGap;
      const pts = [];
      for (let y = gap / 2; y < SVG_H; y += gap) {
        for (let x = gap / 2; x < SVG_W; x += gap) {
          const idx = ((y | 0) * SVG_W + (x | 0)) * 4 + 3; // alpha channel
          if (data[idx] > 90) pts.push([x, y]);
        }
      }
      if (!pts.length) return;
      if (pts.length > this.config.maxDots) {
        // eslint-disable-next-line no-console
        console.warn('[modernvivo] dotfield: ' + pts.length + ' dots exceeds maxDots (' + this.config.maxDots + '); increase sampleGap to lighten it.');
      }

      // centroid (source space) for the radial bloom + scatter geometry
      let cx = 0, cy = 0;
      pts.forEach((p) => { cx += p[0]; cy += p[1]; });
      cx /= pts.length; cy /= pts.length;
      let maxD = 1;
      pts.forEach((p) => { maxD = Math.max(maxD, Math.hypot(p[0] - cx, p[1] - cy)); });

      this._srcPts = pts;
      this._srcCentroid = { x: cx, y: cy };
      this._srcMaxD = maxD;

      this._layout(); // maps source → display, creates bodies + walls
      this._armReveal();
      this._observe(); // pause physics when the section is offscreen
      this._raf = true;
      gsap.ticker.add(this._tick);
      window.addEventListener('pointermove', this._onPointer);
      this.canvas.addEventListener('pointerleave', this._onPointerLeave);
      this._initWidthResize();
    };
    img.src = 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(svg);
  }

  // Compute the source→display transform and (re)build bodies + walls at the current mount size.
  _layout() {
    const dpr = Math.min(devicePixelRatio || 1, this.config.dprCap);
    const r = this.mount.getBoundingClientRect();
    const w = Math.max(1, r.width), h = Math.max(1, r.height);
    this._w = w; this._h = h; this._dpr = dpr;
    this.canvas.width = Math.round(w * dpr);
    this.canvas.height = Math.round(h * dpr);
    this.ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

    const scale = Math.min(w / SVG_W, h / SVG_H) * this.config.fit;
    const offX = (w - SVG_W * scale) / 2;
    const offY = (h - SVG_H * scale) / 2;
    this._scale = scale;
    const toDisp = (p) => [offX + p[0] * scale, offY + p[1] * scale];

    this._dispCentroid = toDisp([this._srcCentroid.x, this._srcCentroid.y]);
    this._dispMaxD = this._srcMaxD * scale;
    this.visualR = Math.max(1.2, this.config.sampleGap * this.config.dotRadiusScale * scale);
    this.physicsR = Math.max(1, this.config.sampleGap * this.config.physicsRadiusScale * scale);

    // (re)create bodies
    if (this.dots.length) {
      Matter.Composite.clear(this.world, false);
      this.dots = [];
      this.walls = [];
    }

    const rev = this.config.reveal;
    const bodies = [];
    this._srcPts.forEach((p, i) => {
      const [hx, hy] = toDisp(p);
      const delayFrac = Math.hypot(p[0] - this._srcCentroid.x, p[1] - this._srcCentroid.y) / this._srcMaxD;
      const delay = delayFrac * rev.staggerSpread;
      // scatter start: random direction, distance scaled to shape radius (deterministic)
      const ang = rand(i + 1) * Math.PI * 2;
      const dist = (rev.scatterMin + rand(i + 7) * (rev.scatterMax - rev.scatterMin)) * this._dispMaxD;
      const fromX = this._dispCentroid[0] + Math.cos(ang) * dist;
      const fromY = this._dispCentroid[1] + Math.sin(ang) * dist;

      // Created DYNAMIC (never toggled static — Body.setStatic(false) on a born-static body
      // restores a corrupt _original → NaN mass). During idle/reveal we simply pin it with
      // setPosition and don't step the engine; "release" just starts Engine.update.
      const body = Matter.Bodies.circle(hx, hy, this.physicsR, {
        friction: 0,
        frictionAir: this.config.physics.frictionAir,
        restitution: this.config.physics.restitution,
      });
      Matter.Body.setPosition(body, { x: fromX, y: fromY });
      Matter.Body.setVelocity(body, { x: 0, y: 0 });
      bodies.push(body);
      this.dots.push({ body, homeX: hx, homeY: hy, fromX, fromY, delay, revealAlpha: 0 });
    });

    // bounding walls so repelled dots can't escape the mount
    const t = 60;
    const mk = (x, y, ww, hh) => Matter.Bodies.rectangle(x, y, ww, hh, { isStatic: true, restitution: 0.4 });
    this.walls = [
      mk(w / 2, -t / 2, w + t * 2, t),
      mk(w / 2, h + t / 2, w + t * 2, t),
      mk(-t / 2, h / 2, t, h + t * 2),
      mk(w + t / 2, h / 2, t, h + t * 2),
    ];
    Matter.Composite.add(this.world, [...bodies, ...this.walls]);

    // reduced motion: skip the show — sit at home, no physics
    if (this.reduced) {
      this.dots.forEach((d) => { Matter.Body.setPosition(d.body, { x: d.homeX, y: d.homeY }); d.revealAlpha = 1; });
      this._phase = 'done';
    }
  }

  _armReveal() {
    if (this.reduced) return;
    const start = this.mount.getAttribute('data-reveal-start') || this.config.reveal.start;
    if (typeof ScrollTrigger !== 'undefined') {
      this._st = ScrollTrigger.create({ trigger: this.mount, start, once: true, onEnter: () => this.startReveal() });
    } else {
      this.startReveal();
    }
  }

  startReveal() {
    if (this._phase !== 'idle') return;
    this._phase = 'revealing';
    this._revealElapsed = 0;
  }

  // Resize only on WIDTH change (mobile scroll changes height only — must not rebuild the field).
  _initWidthResize() {
    let lastW = innerWidth, timer;
    this._onResize = () => {
      clearTimeout(timer);
      timer = setTimeout(() => {
        if (innerWidth === lastW) return;
        lastW = innerWidth;
        this._resize();
      }, 200);
    };
    addEventListener('resize', this._onResize);
  }

  _resize() {
    const phase = this._phase;
    this._layout(); // rebuilds bodies + walls at the new size (leaves them static at scatter start)
    if (this.reduced) return; // _layout already parked them home
    if (phase === 'physics' || phase === 'done') {
      this._release(); // straight back to the live field, no re-bloom
    } else if (phase === 'revealing') {
      this._phase = 'revealing';
      this._revealElapsed = 0; // restart the bloom cleanly at the new geometry
    } // 'idle' → leave armed; the ScrollTrigger from the first _armReveal still fires
  }

  // move all dots home instantly and re-run the bloom (debug/replay)
  replay() {
    this.dots.forEach((d) => {
      Matter.Body.setPosition(d.body, { x: d.fromX, y: d.fromY });
      Matter.Body.setVelocity(d.body, { x: 0, y: 0 });
      d.revealAlpha = 0;
    });
    this._phase = 'idle';
    this._revealElapsed = 0;
    this.startReveal();
  }

  _release() {
    this._phase = 'physics';
    this.dots.forEach((d) => {
      Matter.Body.setPosition(d.body, { x: d.homeX, y: d.homeY });
      Matter.Body.setVelocity(d.body, { x: 0, y: 0 }); // clears stale positionPrev → no phantom launch velocity
      d.revealAlpha = 1;
    });
    if (!this._resolved) {
      this._resolved = true; // fire the sync event once (not again after a resize rebuild)
      document.dispatchEvent(new CustomEvent('dotfield:resolved', { detail: { field: this } }));
      (window.__shapefieldResolved || (window.__shapefieldResolved = new Set())).add('dotfield:resolved');
    }
  }

  _onPointer(e) {
    const r = this.canvas.getBoundingClientRect();
    this.pointer.x = e.clientX - r.left;
    this.pointer.y = e.clientY - r.top;
    this.pointer.active = e.clientX >= r.left && e.clientX <= r.right && e.clientY >= r.top && e.clientY <= r.bottom;
  }

  _tick(time, deltaMS) {
    if (!this._raf) return;
    if (!this.mount.isConnected) { this.destroy(); return; } // barba nav removed the container → clean up
    if (!this._visible && this._phase === 'physics') return; // pause physics offscreen (still cheap)

    const dt = Math.min(33, deltaMS || 16.7);

    if (this._phase === 'revealing') {
      this._revealElapsed += dt / 1000;
      const rev = this.config.reveal;
      let allDone = true;
      for (const d of this.dots) {
        const local = (this._revealElapsed - d.delay) / rev.duration;
        if (local < 1) allDone = false;
        const e = easeOutExpo(Math.max(0, Math.min(1, local)));
        Matter.Body.setPosition(d.body, {
          x: d.fromX + (d.homeX - d.fromX) * e,
          y: d.fromY + (d.homeY - d.fromY) * e,
        });
        d.revealAlpha = Math.max(0, Math.min(1, local * 1.4));
      }
      if (allDone) this._release();
    } else if (this._phase === 'physics') {
      const { stiffness, jitter } = this.config.physics;
      const rep = this.config.repel;
      const pAct = this.pointer.active;
      const px = this.pointer.x, py = this.pointer.y, rr = rep.radius, rr2 = rr * rr;
      for (const d of this.dots) {
        const b = d.body, m = b.mass;
        // soft spring back to home (mass-scaled so motion is uniform across dots)
        let fx = (d.homeX - b.position.x) * stiffness * m;
        let fy = (d.homeY - b.position.y) * stiffness * m;
        // perpetual micro-jitter so the zero-g field never freezes
        fx += (rand(b.id * 3.1 + time * 0.001) - 0.5) * jitter * m;
        fy += (rand(b.id * 7.7 + time * 0.001) - 0.5) * jitter * m;
        // cursor repel
        if (pAct) {
          const dx = b.position.x - px, dy = b.position.y - py, d2 = dx * dx + dy * dy;
          if (d2 < rr2 && d2 > 0.01) {
            const dd = Math.sqrt(d2);
            const f = (1 - dd / rr) * rep.strength * m * 0.02;
            fx += (dx / dd) * f;
            fy += (dy / dd) * f;
          }
        }
        Matter.Body.applyForce(b, b.position, { x: fx, y: fy });
      }
      Matter.Engine.update(this.engine, dt);
      // safety clamp AFTER integration: never let a body's velocity explode (prevents NaN / wall tunnelling)
      const vmax = this.config.physics.maxSpeed;
      for (const d of this.dots) {
        const b = d.body, sp = Math.hypot(b.velocity.x, b.velocity.y);
        if (sp > vmax) Matter.Body.setVelocity(b, { x: (b.velocity.x / sp) * vmax, y: (b.velocity.y / sp) * vmax });
      }
    }

    this._render();
  }

  _render() {
    const ctx = this.ctx;
    ctx.clearRect(0, 0, this._w, this._h);
    ctx.fillStyle = this.config.color;
    const baseA = this.config.opacity;
    const r = this.visualR;
    for (const d of this.dots) {
      if (d.revealAlpha <= 0) continue;
      ctx.globalAlpha = baseA * d.revealAlpha;
      ctx.beginPath();
      ctx.arc(d.body.position.x, d.body.position.y, r, 0, 6.2831853);
      ctx.fill();
    }
    ctx.globalAlpha = 1;
  }

  destroy() {
    this._raf = false;
    gsap.ticker.remove(this._tick);
    window.removeEventListener('pointermove', this._onPointer);
    this._onResize && removeEventListener('resize', this._onResize);
    this.canvas.removeEventListener('pointerleave', this._onPointerLeave);
    this._io && this._io.disconnect();
    this._st && this._st.kill();
    Matter.Composite.clear(this.world, false);
    Matter.Engine.clear(this.engine);
    this.canvas.remove();
    if (this.mount) this.mount.__dotfield = null;
  }
}

// Observe visibility once the instance exists (pause physics offscreen)
DotField.prototype._observe = function () {
  this._io = new IntersectionObserver((e) => (this._visible = e[0].isIntersecting), { threshold: 0 });
  this._io.observe(this.mount);
};

export default DotField;
